# Python Calculator

I'll create a comprehensive calculator with multiple features, from a simple version to a more advanced one.

## 1. Simple Calculator

```python
def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        return "Error: Division by zero!"
    return x / y

def simple_calculator():
    print("=" * 40)
    print("       SIMPLE CALCULATOR")
    print("=" * 40)

    while True:
        print("\nSelect operation:")
        print("1. Add (+)")
        print("2. Subtract (-)")
        print("3. Multiply (*)")
        print("4. Divide (/)")
        print("5. Exit")

        choice = input("\nEnter choice (1-5): ")

        if choice == '5':
            print("Thank you for using the calculator!")
            break

        if choice in ('1', '2', '3', '4'):
            try:
                num1 = float(input("Enter first number: "))
                num2 = float(input("Enter second number: "))
            except ValueError:
                print("Invalid input! Please enter numbers only.")
                continue

            if choice == '1':
                print(f"\n{num1} + {num2} = {add(num1, num2)}")
            elif choice == '2':
                print(f"\n{num1} - {num2} = {subtract(num1, num2)}")
            elif choice == '3':
                print(f"\n{num1} * {num2} = {multiply(num1, num2)}")
            elif choice == '4':
                print(f"\n{num1} / {num2} = {divide(num1, num2)}")
        else:
            print("Invalid choice! Please select 1-5.")

# Run the calculator
if __name__ == "__main__":
    simple_calculator()
```

---

## 2. Advanced Scientific Calculator

```python
import math

class ScientificCalculator:
    def __init__(self):
        self.memory = 0
        self.history = []

    # Basic Operations
    def add(self, x, y):
        return x + y

    def subtract(self, x, y):
        return x - y

    def multiply(self, x, y):
        return x * y

    def divide(self, x, y):
        if y == 0:
            raise ValueError("Cannot divide by zero!")
        return x / y

    def modulus(self, x, y):
        return x % y

    def power(self, x, y):
        return x ** y

    def floor_divide(self, x, y):
        if y == 0:
            raise ValueError("Cannot divide by zero!")
        return x // y

    # Scientific Operations
    def square_root(self, x):
        if x < 0:
            raise ValueError("Cannot calculate square root of negative number!")
        return math.sqrt(x)

    def cube_root(self, x):
        return x ** (1/3) if x >= 0 else -((-x) ** (1/3))

    def factorial(self, x):
        if x < 0 or x != int(x):
            raise ValueError("Factorial requires non-negative integer!")
        return math.factorial(int(x))

    def logarithm(self, x, base=10):
        if x <= 0:
            raise ValueError("Logarithm requires positive number!")
        return math.log(x, base)

    def natural_log(self, x):
        if x <= 0:
            raise ValueError("Natural log requires positive number!")
        return math.log(x)

    def exponential(self, x):
        return math.exp(x)

    # Trigonometric Operations (in degrees)
    def sin(self, x):
        return math.sin(math.radians(x))

    def cos(self, x):
        return math.cos(math.radians(x))

    def tan(self, x):
        return math.tan(math.radians(x))

    def asin(self, x):
        if x < -1 or x > 1:
            raise ValueError("asin requires value between -1 and 1!")
        return math.degrees(math.asin(x))

    def acos(self, x):
        if x < -1 or x > 1:
            raise ValueError("acos requires value between -1 and 1!")
        return math.degrees(math.acos(x))

    def atan(self, x):
        return math.degrees(math.atan(x))

    # Memory Operations
    def memory_store(self, value):
        self.memory = value
        print(f"Stored {value} in memory")

    def memory_recall(self):
        return self.memory

    def memory_clear(self):
        self.memory = 0
        print("Memory cleared")

    def memory_add(self, value):
        self.memory += value
        print(f"Memory now: {self.memory}")

    # History
    def add_to_history(self, expression, result):
        self.history.append(f"{expression} = {result}")
        if len(self.history) > 10:
            self.history.pop(0)

    def show_history(self):
        if not self.history:
            print("No history yet.")
        else:
            print("\n--- Calculation History ---")
            for i, item in enumerate(self.history, 1):
                print(f"{i}. {item}")

    def clear_history(self):
        self.history = []
        print("History cleared")


def run_scientific_calculator():
    calc = ScientificCalculator()

    print("=" * 50)
    print("         SCIENTIFIC CALCULATOR")
    print("=" * 50)

    while True:
        print("\n" + "-" * 50)
        print("MENU:")
        print("-" * 50)
        print("BASIC:      1.Add  2.Subtract  3.Multiply  4.Divide")
        print("            5.Power  6.Modulus  7.Floor Divide")
        print("SCIENTIFIC: 8.√x  9.³√x  10.x!  11.log  12.ln  13.e^x")
        print("TRIG:       14.sin  15.cos  16.tan  17.asin  18.acos  19.atan")
        print("MEMORY:     20.MS  21.MR  22.MC  23.M+")
        print("OTHER:      24.History  25.Clear History  26.Constants")
        print("            0.Exit")
        print("-" * 50)

        choice = input("\nEnter choice: ")

        if choice == '0':
            print("\nThank you for using Scientific Calculator!")
            break

        try:
            # Basic Operations (require 2 numbers)
            if choice in ['1', '2', '3', '4', '5', '6', '7']:
                num1 = float(input("Enter first number: "))
                num2 = float(input("Enter second number: "))

                operations = {
                    '1': (calc.add, '+'),
                    '2': (calc.subtract, '-'),
                    '3': (calc.multiply, '*'),
                    '4': (calc.divide, '/'),
                    '5': (calc.power, '^'),
                    '6': (calc.modulus, '%'),
                    '7': (calc.floor_divide, '//')
                }

                func, symbol = operations[choice]
                result = func(num1, num2)
                expression = f"{num1} {symbol} {num2}"
                print(f"\n✓ {expression} = {result}")
                calc.add_to_history(expression, result)

            # Scientific Operations (require 1 number)
            elif choice in ['8', '9', '10', '11', '12', '13']:
                num = float(input("Enter number: "))

                if choice == '8':
                    result = calc.square_root(num)
                    expression = f"√{num}"
                elif choice == '9':
                    result = calc.cube_root(num)
                    expression = f"³√{num}"
                elif choice == '10':
                    result = calc.factorial(num)
                    expression = f"{int(num)}!"
                elif choice == '11':
                    base = float(input("Enter base (default 10): ") or "10")
                    result = calc.logarithm(num, base)
                    expression = f"log{base}({num})"
                elif choice == '12':
                    result = calc.natural_log(num)
                    expression = f"ln({num})"
                elif choice == '13':
                    result = calc.exponential(num)
                    expression = f"e^{num}"

                print(f"\n✓ {expression} = {result}")
                calc.add_to_history(expression, result)

            # Trigonometric Operations
            elif choice in ['14', '15', '16', '17', '18', '19']:
                num = float(input("Enter number: "))

                trig_ops = {
                    '14': (calc.sin, 'sin'),
                    '15': (calc.cos, 'cos'),
                    '16': (calc.tan, 'tan'),
                    '17': (calc.asin, 'asin'),
                    '18': (calc.acos, 'acos'),
                    '19': (calc.atan, 'atan')
                }

                func, name = trig_ops[choice]
                result = func(num)
                expression = f"{name}({num})"
                print(f"\n✓ {expression} = {result}")
                calc.add_to_history(expression, result)

            # Memory Operations
            elif choice == '20':
                value = float(input("Enter value to store: "))
                calc.memory_store(value)
            elif choice == '21':
                print(f"\nMemory value: {calc.memory_recall()}")
            elif choice == '22':
                calc.memory_clear()
            elif choice == '23':
                value = float(input("Enter value to add to memory: "))
                calc.memory_add(value)

            # Other Operations
            elif choice == '24':
                calc.show_history()
            elif choice == '25':
                calc.clear_history()
            elif choice == '26':
                print("\n--- Mathematical Constants ---")
                print(f"π (pi)     = {math.pi}")
                print(f"e (euler)  = {math.e}")
                print(f"τ (tau)    = {math.tau}")
            else:
                print("Invalid choice! Please try again.")

        except ValueError as e:
            print(f"\n✗ Error: {e}")
        except Exception as e:
            print(f"\n✗ An error occurred: {e}")


if __name__ == "__main__":
    run_scientific_calculator()
```

