## 3. Expression Calculator (Evaluates Mathematical Expressions)

```python
import re
import math

def safe_eval_calculator():
    """Calculator that safely evaluates mathematical expressions"""

    # Safe functions and constants
    safe_dict = {
        'abs': abs,
        'round': round,
        'min': min,
        'max': max,
        'sum': sum,
        'pow': pow,
        'sqrt': math.sqrt,
        'sin': lambda x: math.sin(math.radians(x)),
        'cos': lambda x: math.cos(math.radians(x)),
        'tan': lambda x: math.tan(math.radians(x)),
        'log': math.log10,
        'ln': math.log,
        'exp': math.exp,
        'pi': math.pi,
        'e': math.e,
        'factorial': math.factorial,
    }

    print("=" * 50)
    print("       EXPRESSION CALCULATOR")
    print("=" * 50)
    print("\nYou can type mathematical expressions directly!")
    print("Examples:")
    print("  • 2 + 3 * 4")
    print("  • sqrt(16) + 5")
    print("  • sin(45) * 2")
    print("  • 2 ** 10")
    print("  • pi * 5 ** 2")
    print("\nAvailable functions: sqrt, sin, cos, tan, log, ln, exp, factorial")
    print("Available constants: pi, e")
    print("Type 'quit' to exit\n")

    while True:
        expression = input(">>> ").strip()

        if expression.lower() in ['quit', 'exit', 'q']:
            print("Goodbye!")
            break

        if not expression:
            continue

        try:
            # Replace ^ with ** for power
            expression = expression.replace('^', '**')

            # Evaluate safely
            result = eval(expression, {"__builtins__": {}}, safe_dict)
            print(f"= {result}\n")

        except ZeroDivisionError:
            print("Error: Division by zero!\n")
        except Exception as e:
            print(f"Error: {e}\n")


if __name__ == "__main__":
    safe_eval_calculator()
```

